import"./modulepreload-polyfill-P2Xu9kJm.js";import{C as e,D as t,E as n,O as r,S as i,T as a,k as o,n as s,t as c}from"./scene-transition-4H_bFjt5.js";import{a as l,i as u,n as d,o as f,s as p}from"./additional-collection-_iJ9gP8t.js";import{$ as m,B as h,E as g,H as _,K as v,M as y,N as ee,O as b,P as x,Q as S,T as te,U as C,W as ne,X as re,Y as ie,_t as ae,a as oe,at as se,bt as w,c as ce,ct as T,d as le,et as ue,f as de,ft as fe,g as pe,gt as E,i as me,j as he,k as D,l as ge,lt as _e,mt as ve,n as ye,ot as be,q as O,st as xe,t as Se,tt as Ce,u as we,ut as Te,w as Ee,xt as k,y as A}from"./GLTFLoader-CFTK9j0J.js";import{t as De}from"./Reflector-na-228jW.js";import{a as Oe,i as ke,n as Ae,o as je,s as Me,t as Ne}from"./meshopt_decoder.module-CbQPEPnI.js";var Pe=[{id:`nmc-exhibition`,title:`中国古代玉器`,author:`中国国家博物馆`,url:`https://www.chnmuseum.cn/portals/0/web/zt/202308zggdyq/`},{id:`curatorial`,title:`《神圣与精致——良渚文化玉器展》的内容设计`,author:`穆朝娜 · 北京艺术博物馆`,url:`https://www.bjartmuseum.com/u/cms/www/201405/27120907flck.pdf`},{id:`cong`,title:`玉神面纹琮`,author:`中国国家博物馆`,url:`https://www.chnmuseum.cn/zp/zpml/csp/202107/t20210716_250668.shtml`},{id:`craft`,title:`“千年古城，国之玉器”｜玉见文明`,author:`良渚博物院`,url:`https://www.lzmuseum.cn/LiangBoXinWen/2026295040293.html`},{id:`reuse`,title:`玉琮 · 新00117974`,author:`徐琳 · 故宫博物院`,url:`https://www.dpm.org.cn/collection/jade/233768.html`}],Fe=[{id:`civilization`,number:`01`,title:`以玉见文明`,subtitle:`礼仪 · 身份 · 审美`,english:`JADE AND CIVILIZATION`,tone:`dark`,width:9.2,height:2.8,x:-7.7,z:17.84,rotation:Math.PI,intro:`从史前的礼仪用玉，到后世的佩饰与案头清供，玉器的意义不断变化。形制、纹饰与组合方式，留下了理解古人生活和精神世界的线索。`,sections:[{title:`礼仪与身份`,text:`良渚墓葬中的琮、璧、钺常成组出现。器类、数量和摆放位置，使玉器成为研究礼仪与社会差异的重要材料。`},{title:`器物与背景`,text:`一件玉器不仅有形与色，也有出土环境和流传经历。观看细部，再联系同出的器物，才能理解它在特定时代的意义。`}],image:`collection/supplied/liangzhu.webp`,caption:`良渚玉琮 · 转角纹饰与方圆结构`,sources:[`nmc-exhibition`,`curatorial`,`cong`],sourceLine:`参考：中国国家博物馆《中国古代玉器》；穆朝娜《内容设计》`},{id:`craft`,number:`02`,title:`一块玉的旅程`,subtitle:`从玉料到玉器`,english:`FROM MATERIAL TO OBJECT`,tone:`light`,width:9.2,height:2.8,x:7.7,z:17.84,rotation:Math.PI,intro:`坚韧的玉料，需要经过多道工序才能成器。切割决定大体轮廓，钻孔建立内外结构，雕琢与抛光则让纹饰和光泽逐渐显现。`,sections:[{title:`开料与钻孔`,text:`良渚治玉包括制坯、切割、钻孔与修孔。方形外壁和圆形孔道并非天然形成，而是反复加工的结果。`},{title:`琢纹与磨光`,text:`细密阴线与浅浮雕相互配合，形成纹饰的层次。观察表面时，可以比较纹线、转角与受光面的不同效果。`}],steps:[`制坯 · 切割`,`钻孔 · 修孔`,`琢纹 · 磨光`],image:`collection/supplied/shangzhou.webp`,caption:`商代玉琮 · 观察口沿、器壁与转角`,sources:[`craft`,`cong`],sourceLine:`工艺参考：良渚博物院《玉见文明》；中国国家博物馆《玉神面纹琮》`},{id:`form`,number:`03`,title:`方圆之间`,subtitle:`从形制开始阅读`,english:`READING THE FORM`,tone:`light`,width:5.3,height:2.65,x:-13.8,z:14.1,rotation:Math.PI/2,intro:`琮的方圆结构，有高矮、分节与纹饰的变化。同一器形在不同地区和时代中，呈现出各自的面貌。`,sections:[{title:`三个观察位置`,text:`俯看圆孔与器壁的厚薄；侧看上下射部与器身的比例；沿四角转动，寻找纹饰的重复和衔接。`}],image:`collection/supplied/zhou.webp`,caption:`素面长琮 · 轮廓与玉色`,sources:[`cong`,`nmc-exhibition`],sourceLine:`参考：中国国家博物馆《玉神面纹琮》《中国古代玉器》`},{id:`afterlife`,number:`04`,title:`古玉的新生`,subtitle:`收藏、改用与重新理解`,english:`THE AFTERLIFE OF JADE`,tone:`dark`,width:5.3,height:2.65,x:13.8,z:14.1,rotation:-Math.PI/2,intro:`古玉进入后世收藏，也可能被改作新器。器物的制作时代，与它被题咏、装配和使用的时代，有时相隔数千年。`,sections:[{title:`一件琮的两段历史`,text:`故宫藏御题两节人面纹琮原属良渚文化。清代为其配入珐琅铜胆，改作香熏，并在内壁刻下乾隆御题诗。原器与后配构件，记录着不同的观看方式。`}],image:`collection/supplied/songmingqing.webp`,caption:`两节纹饰与后配构件 · 结合馆藏记录阅读`,sources:[`reuse`],sourceLine:`参考：徐琳《玉琮》，故宫博物院，文物号新00117974`}],Ie=[{id:`baike-bi`,author:`百度百科`,title:`玉璧 · 器形释义`,url:`https://baike.baidu.com/item/玉璧/8865161`},{id:`baike-yue`,author:`百度百科`,title:`玉钺 · 礼器释义`,url:`https://baike.baidu.com/item/玉钺/1055292`},{id:`nmc-bi`,author:`中国国家博物馆`,title:`玉璧`,url:`https://www.chnmuseum.cn/zp/zpml/kgfjp/202104/t20210415_249735.shtml`},{id:`lzm-trident`,author:`良渚博物院`,title:`三叉形器`,url:`https://www.lzmuseum.cn/YuQi/20198121782.html`},{id:`lzm-yue`,author:`良渚博物院`,title:`玉钺`,url:`https://www.lzmuseum.cn/YuQi/2019611219610.html`}],Le=[{id:`cong`,unit:1,floor:0,title:`玉琮`,theme:`方圆载礼`,english:`CONG · FORM AND RITUAL`,image:`collection/supplied/liangzhu.webp`,intro:`外方内圆的器身，将轮廓、孔道与转角连成一个整体。良渚文化的玉琮常以分节和重复纹样组织器表，成为认识史前礼仪的重要材料。`,body:`从低矮宽阔到修长素面，从细密纹饰到后世的重新装配，沿展柜比较器物的不同面貌。玉琮的历史，也是一部关于制作、使用与收藏的历史。`,guide:`一层 · 玉琮专题    /    二层 · 玉器形制`,source:`参考：中国国家博物馆《玉神面纹琮》；故宫博物院《玉琮》`},{id:`jade`,unit:2,floor:4.6,title:`玉器`,theme:`琢玉成章`,english:`JADE · OBJECTS AND ORNAMENT`,image:`collection/jade-forms/jade-bi.webp`,intro:`玉器既有礼仪用器，也有佩饰和其他用具。圆板形的璧、具有刃部轮廓的钺，以及带有穿孔的饰件，呈现出不同的形制与组合方式。`,body:`从轮廓认识器名，从穿孔理解连接，再从纹饰观察工艺。将器物放回具体的考古背景中，才能进一步讨论它的用途和意义。`,guide:`二层 · 玉器形制    /    璧 · 钺 · 冠饰 · 佩饰`,source:`参考：百度百科《玉璧》《玉钺》；中国国家博物馆、良渚博物院馆藏说明`}],j=(e,t,n,r,i,a,o,s,c,l,u)=>({id:e,floor:t,x:n,z:r,rotation:i,title:a,subtitle:o,image:s,text:c,detail:l,source:u,width:5.2,height:2.72}),M=[j(`cong-low`,0,-13.76,-1.5,Math.PI/2,`器身的比例`,`04 / 高与低的对照`,`collection/supplied/liangzhu.webp`,`低矮的器身，让口沿与转角集中在较短的距离内。对照附近的高体玉琮，观察孔径、壁厚与器高的关系，体会方圆结构中的不同变化。`,`图示：低体玉琮 · 从器形进入细节。`,`中国国家博物馆《玉神面纹琮》；本馆展品图像`),j(`cong-plain`,0,13.76,-1.5,-Math.PI/2,`素面也有语言`,`05 / 光泽与轮廓`,`collection/new-jades/qijia-plain.webp`,`没有密集纹样时，转角、棱线与玉色成为观察的重点。随着视角变化，受光面和背光面交替显现，让器壁的厚薄与曲面更容易辨认。`,`图示：齐家素面玉琮 · 缓慢转动模型观察表面。`,`本馆展品图像 · 形态观察`),{...j(`cong-cut`,0,-13.76,-10,Math.PI/2,`琢磨之间`,`06 / 孔道与刻线`,`collection/supplied/shangzhou.webp`,`切割建立轮廓，钻孔形成内外关系，刻纹与磨光完成表面。将孔口、转角和纹线放在一起观察，可以把抽象的工序转化为具体的观看线索。`,`沿口缘观察，再把目光移向器壁和纹饰。`,`良渚博物院《玉见文明》`),width:4.2},{...j(`cong-later`,0,13.76,-10,-Math.PI/2,`方圆的延续`,`07 / 器形与沿用`,`collection/supplied/zenghouyi.webp`,`圆形孔口与方形外壁，形成玉琮鲜明的轮廓。低矮器身集中呈现孔径、壁厚和转角的关系，素净的玉面则显露局部色斑与光泽。`,`图示：战汉时期玉琮 · 对照不同器形观看。`,`本馆展品图像 · 形态观察`),width:4.2},j(`cong-structure`,0,-6.3,-31.79,0,`从方到圆`,`01 / 结构的秩序`,`collection/supplied/zhou.webp`,`方形外壁与圆形孔道，是认识玉琮的起点。比较器身高矮、壁厚和上下凸出的射部，可以看见同一器类中的多种比例。`,`观看提示：先俯看孔口，再沿四角观察侧面。`,`中国国家博物馆《玉神面纹琮》`),j(`cong-pattern`,0,6.3,-31.79,0,`转角有纹`,`02 / 纹样的展开`,`collection/supplied/shangzhou.webp`,`纹饰并不只属于正面。横向分节、细密刻线和转角处的形象，共同构成器物的视觉秩序。观察纹线如何越过四角，能读到更多细节。`,`观看提示：比较素面器与有纹器的受光变化。`,`中国国家博物馆《玉神面纹琮》`),j(`bi`,4.6,-13.76,6.5,Math.PI/2,`璧 · 圆中有孔`,`01 / 礼仪与形制`,`collection/jade-forms/jade-bi.webp`,`玉璧呈圆板状，中央有孔。不同年代的璧，在厚薄、孔径和纹饰上各有变化；有的素面磨光，有的以重复纹样组织表面。`,`从圆周、孔壁和器面三个位置，比较加工与装饰。`,`百度百科《玉璧》；中国国家博物馆《玉璧》`),j(`yue`,4.6,13.76,-6,-Math.PI/2,`钺 · 权力之形`,`02 / 从形制到身份`,`collection/jade-forms/jade-yue.webp`,`玉钺与斧钺形制相联系。在良渚文化中，钺与琮、璧构成重要的用玉组合；墓葬中的位置与组合，是讨论其身份象征的依据。`,`观察刃部、肩部和孔道，想象器物如何装柄。`,`百度百科《玉钺》；良渚博物院《玉钺》`),j(`trident`,4.6,-13.76,-17,Math.PI/2,`三叉 · 冠饰之美`,`03 / 连接与组合`,`collection/jade-forms/jade-trident-a.webp`,`三叉形器上端分为三叉，常见钻孔。良渚墓葬中，这类器物多出现在头部附近，常与玉管相接，被认为与冠帽装饰有关。`,`孔的方向与位置，为理解穿缀方式提供了线索。`,`良渚博物院《三叉形器》`),j(`tube`,4.6,13.76,-17,-Math.PI/2,`管 · 穿连成组`,`04 / 从单件到组合`,`collection/jade-forms/jade-tube.webp`,`管状玉器以贯通孔道形成鲜明轮廓。良渚三叉形器的出土组合中，可见玉管相接；这种联系提示我们，单件器物也可能属于更大的装饰组合。`,`比较孔道的方向、外形的比例与两端的磨制。`,`良渚博物院《三叉形器》`),j(`grain`,4.6,-6.3,-31.79,0,`纹饰的节奏`,`05 / 重复与变化`,`collection/final-jades/grain-bi.webp`,`细小单元有序排列，能够形成连续的器表纹样。看展时可先看整体分区，再靠近观察一处纹饰，比较线条、凸起与留白。`,`图示：战国谷纹玉璧 · 对照展柜观察细部。`,`百度百科《玉璧》；本馆展品图像`),j(`pendant`,4.6,6.3,-31.79,0,`佩玉成章`,`06 / 轮廓与装饰`,`collection/final-jades/double-dragon-heng.webp`,`弧形器身与两端的动物纹样，把轮廓和装饰结合在一起。循着器缘观察曲线，再寻找穿孔，可体会佩饰在连接与观看之间的设计。`,`图示：汉代双龙首玉珩 · 留意两端与中部的呼应。`,`本馆展品图像 · 形态观察`),j(`upper-entry`,4.6,-3,17.8,Math.PI,`从器形走近玉`,`08 / 第二单元导览`,`collection/final-jades/chi-plaque.webp`,`这一层从不同器形出发，呈现玉器的轮廓、穿孔和装饰。沿两侧展柜前行，比较圆形、弧形与片状器物，再回到实物细节。`,`单元路线：璧与钺 → 冠饰与连接 → 纹饰与佩玉。`,`本馆玉器形制陈列`),j(`upper-craft`,4.6,3,17.8,Math.PI,`在细节中相遇`,`09 / 制作留下的线索`,`collection/jade-forms/jade-trident-b.webp`,`钻孔、刻线与磨光，使坚硬玉料成为有秩序的器物。对比不同形制的局部，观察孔壁、棱线和表面光泽，能更具体地体会治玉工艺。`,`靠近展柜按 E，可旋转模型并查看对应照片。`,`良渚博物院《玉见文明》《三叉形器》`)],Re=[-1,1].flatMap(e=>[3,-6,-14].map(t=>({x:e*11.7,z:t,side:e}))),ze=[...p,l[0]].map((e,t)=>{let n=Re[Math.floor(t/2)];return{...e,x:n.x,z:n.z+(t%2?.68:-.68),y:0,angle:0,displayYaw:e.archive===`玉`?-n.side*Math.PI/2:0,baseY:1.108,maxWidth:.52,maxHeight:1.12,lampY:2.65,cabinetIndex:Math.floor(t/2)}}),Be=f.map((e,t)=>({...e,x:t%2?3.2:-3.2,z:6-Math.floor(t/2)*9,y:4.6,angle:0,baseY:5.708,maxWidth:.82,maxHeight:1.16,lampY:7.25,caseRadius:1})),Ve=[-1,1].flatMap(e=>[4,-6].map(t=>({x:e*8.6,z:t,y:4.6,side:e}))),He=l.s